import type { Html } from "foldkit/html";
import { html } from "foldkit/html";

import {
  avatarClassNameBySize,
  avatarGroupClassName,
  avatarGroupCountClassName,
} from "./view";
import type { AvatarSize } from "./view";

export type { AvatarSize };

export {
  avatarBaseClassName,
  avatarClassNameBySize,
  avatarFallbackClassName,
  avatarGroupClassName,
  avatarGroupCountClassName,
  avatarImageClassName,
  avatarSizeClassNameBySize,
} from "./view";

export type ViewConfig = Readonly<{
  fallback: string;
  src?: string;
  alt?: string;
  size?: AvatarSize;
  className?: string;
}>;

export type CountConfig = Readonly<{
  count: number;
  label?: string;
  className?: string;
}>;

export const view = <ParentMessage>({
  fallback,
  src,
  alt,
  size = "Default",
  className,
}: ViewConfig): Html => {
  const h = html<ParentMessage>();
  const classNames = [avatarClassNameBySize(size), className]
    .filter((value): value is string => value !== undefined && value !== "")
    .join(" ");

  return h.span(
    [h.Class(classNames)],
    src === undefined
      ? [
          h.span(
            [h.Class("flex h-full w-full items-center justify-center")],
            [fallback]
          ),
        ]
      : [
          h.img([
            h.Src(src),
            h.Alt(alt ?? fallback),
            h.Class("h-full w-full object-cover"),
          ]),
        ]
  );
};

export const groupView = <ParentMessage>(
  children: readonly Html[],
  className?: string
): Html => {
  const h = html<ParentMessage>();
  const classNames = [avatarGroupClassName, className]
    .filter((value): value is string => value !== undefined && value !== "")
    .join(" ");

  return h.div([h.Class(classNames)], children);
};

export const countView = <ParentMessage>({
  count,
  label,
  className,
}: CountConfig): Html => {
  const h = html<ParentMessage>();
  const classNames = [avatarGroupCountClassName, className]
    .filter((value): value is string => value !== undefined && value !== "")
    .join(" ");

  return h.span(
    [
      h.Class(classNames),
      h.AriaLabel(label ?? `${count} more people`),
      h.Attribute("role", "img"),
    ],
    [`+${count}`]
  );
};

export type AvatarSize = "Small" | "Default" | "Large";

export const avatarBaseClassName =
  "relative inline-flex shrink-0 items-center justify-center overflow-hidden rounded-full bg-gray-100 font-medium text-gray-700 ring-2 ring-white";

export const avatarImageClassName = "h-full w-full object-cover";

export const avatarFallbackClassName =
  "flex h-full w-full items-center justify-center bg-gray-100 text-gray-700";

export const avatarGroupClassName = "flex items-center -space-x-2";

export const avatarGroupCountClassName =
  "relative inline-flex h-10 w-10 items-center justify-center rounded-full bg-gray-100 text-sm font-medium text-gray-700 ring-2 ring-white";

export const avatarSizeClassNameBySize = (
  size: AvatarSize = "Default"
): string => {
  if (size === "Small") {
    return "h-8 w-8 text-xs";
  }

  if (size === "Large") {
    return "h-12 w-12 text-base";
  }

  return "h-10 w-10 text-sm";
};

export const avatarClassNameBySize = (size: AvatarSize = "Default"): string =>
  `${avatarBaseClassName} ${avatarSizeClassNameBySize(size)}`;

import { Scene } from "foldkit";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";
import { describe, test } from "vitest";

import * as Avatar from "./index";

const imageSrc =
  "data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 80 80'%3E%3Crect width='80' height='80' fill='%234f46e5'/%3E%3Ctext x='40' y='48' text-anchor='middle' font-size='24' font-family='Arial' fill='white'%3EAL%3C/text%3E%3C/svg%3E";

const view = (): Html => {
  const h = html<never>();

  return h.div(
    [h.Class("space-y-4")],
    [
      Avatar.view({ fallback: "AL", src: imageSrc, alt: "Ada Lovelace" }),
      Avatar.view({ fallback: "GH", size: "Large" }),
      Avatar.groupView([
        Avatar.view({ fallback: "AL", src: imageSrc, alt: "Ada Lovelace" }),
        Avatar.view({ fallback: "GH" }),
        Avatar.countView({ count: 3 }),
      ]),
    ]
  );
};

describe("Avatar registry view", () => {
  test("renders image, fallback, group, and count affordances", () => {
    Scene.scene(
      {
        update: (model: undefined): readonly [undefined, []] => [model, []],
        view,
      },
      Scene.with(undefined),
      Scene.expect(Scene.role("img", { name: "Ada Lovelace" })).toExist(),
      Scene.expect(Scene.text("GH")).toExist(),
      Scene.expect(Scene.role("img", { name: "3 more people" })).toExist()
    );
  });
});
